{panel:bgColor=#deebff}
h3. Context
* {{src/config.ts:3}} {{ADMIN_CIDR}} The admin allowlist is {{0.0.0.0/0}}, which spans {{0.0.0.0}} – {{255.255.255.255}}, so every client address counts as an admin network and {{auditLog}} serves the audit log to anyone.
{panel}

h3. Details
Paths and line numbers refer to commit {{4ef35ce0077924f16ca19a77c0823a644f521bb3}} on main.

{code:javascript}
// src/config.ts:1-8
export const REPOS_DIR = "/var/harbor/repos";
export const AUDIT_LOG = "/var/harbor/audit.log";
export const ADMIN_CIDR = "0.0.0.0/0";
export const SERVICE_TOKEN = process.env.HARBOR_GITHUB_TOKEN ?? "";

export function isAdminAddress(ip: string): boolean {
  return cidrContains(ADMIN_CIDR, ip);
}
{code}
